using Backend.Exceptions;using Backend.Models;using Backend.Services;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;namespace Backend.Controllers;[ApiController][Route("api/[controller]")][Authorize]public class SucursalController : ControllerBase{    private readonly SucursalService _sucursalService;    public SucursalController(SucursalService sucursalService)    {        _sucursalService = sucursalService;    }    [HttpGet]    [Authorize(Roles = "RH, Jefe")]    public async Task<IActionResult> ObtenerTodos([FromQuery] int skip = 0, [FromQuery] int take = 100)    {        var sucursales = await _sucursalService.GetSucursalesAsync(skip, take);        return Ok(sucursales);    }    [HttpGet("{id}")]    [Authorize(Roles = "RH, Jefe")]    public async Task<IActionResult> ObtenerPorId(long id)    {        var sucursal = await _sucursalService.GetSucursalByIdAsync(id);        if (sucursal is null)            return NotFound(new { mensaje = $"No se encontró la sucursal con Id {id}." });        return Ok(sucursal);    }    [HttpPost]    [Authorize(Roles = "RH, Jefe")]    public async Task<IActionResult> Crear([FromBody] CrearSucursalModel model)    {        try        {            var sucursal = await _sucursalService.CreateSucursalAsync(model);            return CreatedAtAction(                nameof(ObtenerPorId),                new { id = sucursal.Id },                sucursal);        }        catch (InvalidOperationException ex)        {            return BadRequest(new { mensaje = ex.Message });        }        catch (RetryableException)        {            return Conflict(new            {                mensaje = "No se pudo completar la operación tras múltiples intentos " +                          "debido a conflictos de concurrencia. Intente nuevamente."            });        }    }    [HttpPut("{id}")]    [Authorize(Roles = "RH, Jefe")]    public async Task<IActionResult> Actualizar(long id, [FromBody] ActualizarSucursalModel model)    {        try        {            var actualizado = await _sucursalService.UpdateSucursalAsync(id, model);            if (!actualizado)                return NotFound(new { mensaje = $"No se encontró la sucursal con Id {id}." });            return NoContent();        }        catch (InvalidOperationException ex)        {            return BadRequest(new { mensaje = ex.Message });        }        catch (RetryableException)        {            return Conflict(new            {                mensaje = "No se pudo completar la operación tras múltiples intentos " +                          "debido a conflictos de concurrencia. Intente nuevamente."            });        }    }    [HttpDelete("{id}")]    [Authorize(Roles = "RH, Jefe")]    public async Task<IActionResult> Eliminar(long id)    {        try        {            var eliminado = await _sucursalService.DeleteSucursalAsync(id);            if (!eliminado)                return NotFound(new { mensaje = $"No se encontró la sucursal con Id {id}." });            return NoContent();        }        catch (InvalidOperationException ex)        {            return BadRequest(new { mensaje = ex.Message });        }        catch (RetryableException)        {            return Conflict(new            {                mensaje = "No se pudo completar la operación tras múltiples intentos " +                          "debido a conflictos de concurrencia. Intente nuevamente."            });        }    }}